const prospectCases=[
{context:'A new RFP arrives. The response is due next week.',pain:'Your team is searching old proposals, dividing up sections, and trying to keep requirements from getting lost.',result:'A working proposal with a clear review path',outputs:[['Requirements','Deliverables, submission rules, and open questions in one review.'],['Response','A tailored narrative, scope, timeline, and investment.'],['Control','Your team edits, checks, and approves the final response.']],custom:['Your proposal templates and brand voice','Your service library and approved case studies','Your review stages and approval owners'],prompt:'“Use our implementation approach to draft the scope, then flag every requirement we have not answered.”',next:1},
{context:'The webinar went well. Now 200 attendees need follow-up.',pain:'A generic email misses the questions people asked and the topics that held their attention.',result:'A relevant conversation for each attendee',outputs:[['First email','A message grounded in the webinar and the attendee’s interests.'],['Useful content','Supporting material matched to the topic or sector.'],['Next touches','Three follow-ups with distinct reasons to reconnect.']],custom:['Your webinars, content library, and audience segments','Your sender voices and review process','Your follow-up timing and handoff rules'],prompt:'“Draft a follow-up for an operations leader who asked about reducing manual reporting. Include the relevant resource.”',next:1},
{context:'New leads arrive from events, referrals, and campaigns.',pain:'Sales sees a list of names, but not a shared explanation of who is a good fit or who should respond.',result:'An actionable queue, with reasoning attached',outputs:[['Priority','Fit and intent signals visible alongside each account.'],['Context','A concise explanation of the likely business opportunity.'],['Ownership','A named owner, a due date, and a next action.']],custom:['Your ideal customer profile and qualification criteria','Your territories, owners, and routing rules','Your CRM fields and lead sources'],prompt:'“Show leads that match our target profile and have a specific operational problem we can help solve.”',next:0},
{context:'You are about to present a new idea to a buying committee.',pain:'The pitch makes sense internally, but finance, operations, and procurement may each hear it differently.',result:'A rehearsal with different stakeholder perspectives',outputs:[['Reactions','Persona-specific questions, objections, and clarity scores.'],['Improvements','Suggestions tied to the parts of the message that need work.'],['Comparison','A view of the original and revised versions.']],custom:['Your buyer roles, sectors, and stakeholder concerns','Your evaluation rubric and scoring weights','Your proposals, messages, and presentation content'],prompt:'“Review this pitch as a CFO, operations director, and procurement lead. Where would each ask for evidence?”',next:0},
{context:'Every department has a plan. Finance needs one budget.',pain:'Assumptions live in emails and spreadsheets, making it difficult to understand the trade-offs behind requests.',result:'A company plan with department-level reasoning',outputs:[['Department plan','Editable spending lines tied to the team’s priorities.'],['Trade-offs','Options for changing investment and balancing the total.'],['Review','Assumptions and decisions captured for sign-off.']],custom:['Your cost categories, departments, and fiscal calendar','Your approval thresholds and finance policies','Your historical spending and planning process'],prompt:'“Help us reduce this department’s plan while protecting the work required for our top two priorities.”',next:1},
{context:'Leadership asks why sales are changing.',pain:'The headline number is easy to find. Explaining the accounts, stages, and trends behind it takes another round of reports.',result:'A leadership view that opens into the detail',outputs:[['Performance','Historical trends and current results in one place.'],['Pipeline','Opportunity-level values, stages, owners, and probability.'],['Outlook','A view of projected revenue and the drivers to inspect.']],custom:['Your sales stages, targets, and reporting definitions','Your regions, products, and account segments','Your CRM and financial reporting sources'],prompt:'“Which opportunities and pipeline changes deserve attention in this week’s sales review?”',next:1},
{context:'A new project needs people who are already committed.',pain:'A staffing decision can solve one project’s problem while quietly overloading another team.',result:'A staffing plan with the capacity impact visible',outputs:[['Availability','A weekly view of assigned hours and remaining capacity.'],['Assignments','Editable allocations across people and projects.'],['Risks','Overloads and gaps that need a staffing decision.']],custom:['Your roles, skills, working hours, and time-off rules','Your project demand and allocation process','Your staffing constraints and approval owners'],prompt:'“Find a way to staff the new project without pushing anyone above their available hours.”',next:0},
{context:'The project involves your team, a contractor, and a client.',pain:'Files, decisions, and updates are scattered across channels, and each person is working from a different picture.',result:'A shared project home with the right access',outputs:[['Work','Tasks, owners, dates, and project progress together.'],['Context','Files and conversations attached to the project.'],['Access','Role-based views for the people doing and approving the work.']],custom:['Your project types, templates, and handoff stages','Your Teams and SharePoint structure','Your employee, contractor, and client permissions'],prompt:'“What changed this week, what is blocked, and which decision does the client need to make?”',next:0},
{context:'The answer is spread across five different reports.',pain:'Teams can read each report, but connecting findings across functions takes time and often depends on one analyst.',result:'A place to explore the business across reports',outputs:[['Overview','Visual summaries of performance across functions.'],['Sources','A report library that keeps the source context accessible.'],['Questions','AI-assisted exploration of patterns and related findings.']],custom:['Your reporting sources and business definitions','Your leadership metrics and dashboard views','Your role-based report access and review cadence'],prompt:'“Compare the sales and delivery reports. Which changes should leadership investigate together?”',next:1},
{context:'The plan depends on growth and conversion assumptions.',pain:'A single forecast hides how much the outcome changes when the assumptions do.',result:'Scenarios that make the uncertainty discussable',outputs:[['Drivers','Editable assumptions with a visible effect on the forecast.'],['Scenarios','Saved alternatives to compare with the baseline.'],['Reasoning','The inputs and model logic behind the outlook.']],custom:['Your revenue or operating model and forecast horizon','Your business drivers and scenario assumptions','Your planning data and management review process'],prompt:'“Compare the base case with slower growth and a lower win rate. Show which driver changes the outcome most.”',next:0},
{context:'There are several good AI ideas. Which one should you fund?',pain:'The opportunity sounds valuable, but the savings, adoption, and ongoing cost have not been tested together.',result:'A business case you can challenge before investing',outputs:[['Economics','Expected benefits compared with build and running costs.'],['Payback','A modeled view of when the investment could be recovered.'],['Sensitivity','The effect of changing adoption and savings assumptions.']],custom:['Your labor costs, benefit categories, and investment rules','Your adoption expectations and operating expenses','Your evidence requirements and decision thresholds'],prompt:'“Would this project still make sense if adoption were lower than expected and operating costs increased?”',next:2},
{context:'Several builds are underway. You need a clear status.',pain:'Progress is spread across updates, and it is hard to tell which milestone or decision actually needs your attention.',result:'A portfolio view that connects status to action',outputs:[['Portfolio','Each initiative’s current state in a single view.'],['Delivery','Milestones and timing you can open and inspect.'],['Decisions','Outstanding questions and risks that need an owner.']],custom:['Your client projects and delivery stages','Your milestone definitions and reporting cadence','Your escalation rules and stakeholder access'],prompt:'“Summarize the projects that need a decision from us this week and explain what is waiting on that decision.”',next:2},
{context:'Your sales day starts with research instead of conversations.',pain:'Finding relevant companies and building a thoughtful first message consumes the time you wanted to spend reaching out.',result:'A researched starting point for your morning outreach',outputs:[['Accounts','Companies selected around your target profile and signals.'],['Context','Research to help you judge the relevance of each prospect.'],['Drafts','Three email and LinkedIn approaches you can edit and review.']],custom:['Your industries, geography, size, and target roles','Your research signals and account exclusions','Your outreach voice, offers, and review preferences'],prompt:'“Find manufacturers in our target region with a workflow we can improve, and draft three relevant outreach angles.”',next:0}
];
function showProspectExample(){const p=prospectCases[current];draw('See the opportunity',`<div class="case-kicker">ILLUSTRATIVE SCENARIO · ${esc(toolsList[current][0])}</div><h2 class="case-title">${esc(p.context)}</h2><p class="case-problem">${esc(p.pain)}</p><div class="case-prompt"><span>AN EXAMPLE REQUEST</span><p>${esc(p.prompt)}</p></div><h3 class="case-section-title">What your team could work with</h3>${p.outputs.map(([name,body],i)=>`<div class="case-deliverable"><span>0${i+1}</span><div><b>${esc(name)}</b><p>${esc(body)}</p></div></div>`).join('')}<div class="case-custom"><h3>Built around your business</h3>${p.custom.map(x=>`<p>${icon('check')}${esc(x)}</p>`).join('')}</div><p class="case-disclosure">This is an example of the workflow we can build, not a customer result. The interactive demo uses sample data and simulated AI. Data connections and business rules are tailored during implementation.</p>${ib('Explore this in the demo',`closeDrawer();exploreHeaderStep(${p.next})`,'arrow','primary')}`)}
let prospectPanelMode='example';
function setProspectPanel(mode){prospectPanelMode=mode;renderProspectPanel()}
function renderProspectPanel(){const host=document.querySelector('.story-result');if(!host||current<0)return;const p=prospectCases[current];host.innerHTML=`<div class="prospect-panel-tabs" role="tablist" aria-label="Explore the opportunity">${['example','result','tailor'].map((x,i)=>`<button role="tab" aria-selected="${prospectPanelMode===x}" class="${prospectPanelMode===x?'selected':''}" onclick="setProspectPanel('${x}')">${['The challenge','The result','Your business'][i]}</button>`).join('')}</div><div class="prospect-panel-content">${prospectPanelMode==='example'?`<span class="case-kicker">PICTURE THIS</span><h2>${esc(p.context)}</h2><p>${esc(p.pain)}</p>`:prospectPanelMode==='result'?`<span class="case-kicker">WHAT WE CAN BUILD</span><h2>${esc(p.result)}</h2><div class="prospect-output-list">${p.outputs.map(([x,y])=>`<div><b>${esc(x)}</b><p>${esc(y)}</p></div>`).join('')}</div>`:`<span class="case-kicker">TAILORED TO YOUR TEAM</span><h2>Your workflow shapes the application.</h2><div class="prospect-tailor-list">${p.custom.map(x=>`<p>${icon('check')}${esc(x)}</p>`).join('')}</div>`}</div><button class="prospect-example-button" onclick="showProspectExample()">See a concrete example <span>↗</span></button><small class="prospect-sample-label">Illustrative workflow · Explore the sample app below</small>`}
const renderBeforeProspects=render;render=function(){renderBeforeProspects();if(current<0)return;renderProspectPanel();const main=document.querySelector('.story-main');main.insertAdjacentHTML('beforeend',`<div class="prospect-hero-actions"><button class="primary" onclick="showProspectExample()">Show me what this could do ${icon('arrow')}</button><button onclick="exploreHeaderStep(0)">Try the workspace ${icon('arrow')}</button></div>`)};render();
